 profile=fetchStored(PROFILE)||{name:'Administrator Koteka Digital',email:DEMO_USER,role:'Pengelola Konten',phone:'',bio:'',photo:''};
 persist(STORE,data);persist(LOGS,logs);persist(TRAFFIC,traffic);
