function writeLog(kind,module,description,actor){logs=fetchStored(LOGS)||[];logs.unshift({id:UID(),date:new Date().toISOString(),kind,module,actor:actor||profile?.name||'Administrator',description});logs=logs.slice(0,1500);persist(LOGS,logs)}
