function toast(message,type='ok'){let c=$('#toastContainer'),x=document.createElement('div');x.className='toast '+(type==='error'?'error':'');x.textContent=message;c.append(x);setTimeout(()=>x.remove(),3500)}
function closeMobileSidebar(){const sidebar=$('#sidebar');sidebar.classList.remove('open');$('#sidebarOverlay').hidden=true;document.body.classList.remove('drawer-open');updateSidebarButton()}
function updateSidebarButton(){
 const mobile=matchMedia('(max-width:1050px)').matches,opened=mobile?$('#sidebar').classList.contains('open'):!document.documentElement.classList.contains('workspace-collapsed');
 const b=$('#sidebarToggle');if(!b)return;
 b.setAttribute('aria-expanded',String(opened));b.setAttribute('aria-label',opened?'Tutup sidebar':'Buka sidebar');b.title=opened?'Tutup sidebar':'Buka sidebar';
 b.innerHTML=opened?'<svg class="sidebar-toggle-icon" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" aria-hidden="true" focusable="false"><path d="M6 6l12 12M18 6 6 18"/></svg>':window.KotekaFA.icon('fa-bars',17);
 const holder=opened?$('.sidebar-brand'):$('.top-left');
 if(b.parentElement!==holder){if(opened)holder.append(b);else holder.prepend(b);}
}
function toggleSidebar(){if(matchMedia('(max-width:1050px)').matches){let opening=!$('#sidebar').classList.contains('open');$('#sidebar').classList.toggle('open',opening);$('#sidebarOverlay').hidden=!opening;document.body.classList.toggle('drawer-open',opening)}else{let value=!document.documentElement.classList.contains('workspace-collapsed');document.documentElement.classList.toggle('workspace-collapsed',value);try{localStorage.setItem('koteka.sidebar.collapsed',value?'1':'0')}catch{};setTimeout(()=>{if(route==='traffic')drawTrafficCharts();if(route==='dashboard')drawDashboardCharts()},250)}updateSidebarButton()}
