 let counts=[['Layanan',(data.serviceItems||[]).length,'Kelompok layanan','services'],['Portofolio',(data.portfolioItems||[]).length,'Karya di Workspace','portfolio'],['Artikel',(data.blogPosts||[]).length,'Konten artikel','articles'],['Testimoni',(data.testimonials||[]).length,'Ulasan yang dikelola','testimonials']];
