function groupKey(d,type){let x=new Date(d);switch(type){case 'detik':{let p=witParts(x);return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}:${p.second}`;}case 'menit':{let p=witParts(x);return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}`;}case 'jam':{let p=witParts(x);return `${p.year}-${p.month}-${p.day}T${p.hour}`;}case 'hari':return dateISO(x);case 'minggu':{let date=new Date(x);date.setHours(0,0,0,0);date.setDate(date.getDate()-(date.getDay()+6)%7);return dateISO(date)}case 'bulan':return dateISO(x).slice(0,7);case 'tahun':return witParts(x).year;default:return dateISO(x)}}
