function aggregateTraffic(f=filters){let visits=filterVisits(f),limit=f.granularity==='detik'?60:f.granularity==='menit'?60:f.granularity==='jam'?48:f.granularity==='hari'?45:f.granularity==='minggu'?35:f.granularity==='bulan'?24:20;
 const now=Date.now();if(f.granularity==='detik')visits=visits.filter(v=>now-new Date(v.date).getTime()<=60000);if(f.granularity==='menit')visits=visits.filter(v=>now-new Date(v.date).getTime()<=3600000);if(f.granularity==='jam')visits=visits.filter(v=>now-new Date(v.date).getTime()<=172800000);
 let groups=new Map();visits.forEach(v=>{let k=groupKey(v.date,f.granularity);if(!groups.has(k))groups.set(k,{key:k,label:formatBucket(k,f.granularity),views:0,visitors:new Set(),channel:f.channel==='all'?'Semua':f.channel});let g=groups.get(k);g.views+=v.views;if(v.aggregate)g.aggregateUsers=(g.aggregateUsers||0)+(Number(v.users)||0);else g.visitors.add(v.session)});
 return [...groups.values()].sort((a,b)=>a.key.localeCompare(b.key)).slice(-limit).map(x=>({key:x.key,label:x.label,views:x.views,unique:x.visitors.size+(x.aggregateUsers||0),channel:x.channel}))}
