 if(f.type==='select')return `<div class="field"><label for="f_${f.name}">${esc(f.label)}</label><select id="f_${f.name}" name="${f.name}">${f.options.map(o=>`<option value="${attr(o)}" ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;
