function imageToWebp(file){return new Promise((resolve,reject)=>{if(!['image/jpeg','image/png','image/webp'].includes(file.type))return reject(new Error('Format gambar harus JPG, PNG atau WebP.'));if(file.size>8*1024*1024)return reject(new Error('File gambar maksimum 8 MB.'));let url=URL.createObjectURL(file),img=new Image();img.onload=()=>{try{let scale=Math.min(1,1200/img.width,900/img.height),cv=document.createElement('canvas');cv.width=Math.max(1,Math.round(img.width*scale));cv.height=Math.max(1,Math.round(img.height*scale));let cx=cv.getContext('2d');cx.drawImage(img,0,0,cv.width,cv.height);let output=cv.toDataURL('image/webp',.76);URL.revokeObjectURL(url);if(output.length>780000)reject(new Error('Gambar terlalu besar. Gunakan WebP yang lebih ringan.'));else resolve(output)}catch(e){URL.revokeObjectURL(url);reject(e)}};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Gambar gagal dibaca.'))};img.src=url})}
