function saveProfile(ev){ev.preventDefault();const f=$('#profileEditForm');if(!f.reportValidity())return;let next={name:$('#profileName').value.trim(),email:$('#profileEmail').value.trim(),role:$('#profileRole').value.trim(),phone:$('#profilePhone').value.trim(),bio:$('#profileBio').value.trim(),photo:pendingPhoto};if(!next.name||!next.email)return toast('Nama dan email wajib diisi.','error');if(!persist(PROFILE,next))return;profile=next;writeLog('editor','Profil Administrator','Memperbarui profil administrator');updateProfileUI();closeProfileDialog();toast('Profil administrator berhasil disimpan.')}
function searchEntries(text){const q=text.toLocaleLowerCase('id').trim();if(q.length<2)return [];const matches=[],add=(item)=>{if(matches.length<40)matches.push(item)};
 for(let n of [...navTop,...navContent])if(n[1].toLowerCase().includes(q))add({module:n[0],label:n[1],type:'Menu',key:'',id:''});
 const mappings={home:'home',about:'about',teamMembers:'about',serviceCategories:'services',serviceItems:'services',pricingIntro:'pricing',pricingPlans:'pricing',pricingTable:'pricing',pricingExtras:'pricing',portfolioItems:'portfolio',blogPosts:'articles',testimonials:'testimonials',faqs:'faq',contact:'contact',contactChannels:'contact',socialLinks:'contact'};
 for(let [key,mod] of Object.entries(mappings)){let a=data[key],items=Array.isArray(a)?a:[a];for(let item of items){if(!item)continue;let haystack=Object.values(item).filter(v=>typeof v==='string'||typeof v==='number').join(' ').toLocaleLowerCase('id');if(haystack.includes(q)){add({module:mod,key,id:item._id||'',setting:!Array.isArray(a),label:titleOf(item)==='Tanpa judul'?(SCHEMA[key]?.label||NAV[mod][1]):titleOf(item),type:SCHEMA[key]?.label||'Konten'});if(matches.length>=40)return matches}}}
 return matches}
function closeSearch(){$('#globalSearchResults').hidden=true;$('#globalSearch').setAttribute('aria-expanded','false')}
function showSearch(value){const results=$('#globalSearchResults'),list=searchEntries(value);if(value.trim().length<2){closeSearch();return}results.innerHTML=`<div class="global-results-title">HASIL PENCARIAN <span>${list.length}${list.length===40?'+':''}</span></div>${list.length?list.map((x,i)=>`<button type="button" role="option" data-search-hit data-module="${attr(x.module)}" data-key="${attr(x.key||'')}" data-id="${attr(x.id||'')}" data-setting="${x.setting?'true':'false'}"><span class="search-hit-icon">${ico(NAV[x.module][2],15)}</span><span><strong>${esc(short(x.label,72))}</strong><small>${esc(x.type)} · ${esc(NAV[x.module][1])}</small></span>${ico('arrow',12)}</button>`).join(''):'<div class="search-empty">Tidak ada hasil. Coba judul, nama, kategori, atau kata kunci lain.</div>'}`;results.hidden=false;$('#globalSearch').setAttribute('aria-expanded','true')}

function applyWorkspaceTheme(value){let dark=value; if(typeof dark!=='boolean'){dark=false;try{dark=localStorage.getItem('koteka.workspace.theme')==='dark'}catch{}}document.documentElement.classList.toggle('kd-dark',dark);const btn=$('#themeButton');if(btn){btn.innerHTML=`<span class="kd-theme-symbol ${dark?'':'is-active'}">${window.KotekaFA.icon('fa-sun',20)}</span><span class="kd-theme-symbol ${dark?'is-active':''}">${window.KotekaFA.icon('fa-moon',20)}</span>`;btn.title=dark?'Mode gelap aktif · Gunakan mode terang':'Mode terang aktif · Gunakan mode gelap';btn.setAttribute('aria-label',btn.title);btn.setAttribute('aria-pressed',String(dark))}if(route==='dashboard')requestAnimationFrame(drawDashboardCharts);if(route==='traffic')requestAnimationFrame(drawTrafficCharts)}
function updateInboxBadge(){const visible=Math.max(0,inboxUnread);$$('[data-inbox-badge]').forEach(el=>{el.textContent=visible>99?'99+':String(visible);el.hidden=visible===0});const btn=$('#notificationButton');if(btn){const label=visible?`${visible} pesan konsultasi belum dibaca. Buka Pesan Masuk`:'Buka Pesan Masuk. Tidak ada pesan belum dibaca';btn.setAttribute('aria-label',label);btn.title=label;btn.classList?.toggle('has-unread',visible>0)}}
function renderInbox(){return heading('Pesan Masuk','Permintaan konsultasi dari form website. Data simulasi lokal ditandai secara terpisah.')+`<section class="panel panel-pad kd-inbox-panel"><div class="panel-head"><div><h2><i class="fa-solid fa-envelope" aria-hidden="true"></i> Konsultasi Pelanggan</h2><p>Pesan asli tersimpan pada server. Simulasi lokal tersimpan hanya pada browser ini.</p></div><button class="btn btn-light" type="button" data-action="refreshInbox">${ico('refresh',16)} Segarkan</button></div><div id="inboxStatus" class="kd-inbox-status" role="status">Memuat pesan...</div><div id="inboxList"></div></section>`}
async function loadInbox(silent=false){if($('#appShell').hidden||inboxLoading||inboxAuthenticating)return;inboxLoading=true;try{const res=await (window.KotekaConsultation?.request || fetch)('/api/inbox',{credentials:'same-origin',headers:{Accept:'application/json'},cache:'no-store'});const data=await res.json().catch(()=>({}));if(!res.ok){if(res.status===401){inboxItems=[];inboxUnread=0;inboxKnownIds=null;updateInboxBadge()}if(route==='inbox'){const status=$('#inboxStatus');if(status&&!(res.status===401&&$('#serverInboxLogin')))status.innerHTML=res.status===401?`<strong>Login server diperlukan</strong><p>Masukkan email dan kata sandi administrator server untuk mengakses pesan dan mengaktifkan notifikasi konsultasi.</p><form id="serverInboxLogin" class="kd-inbox-login"><label>Email administrator<input name="email" type="email" autocomplete="username" required></label><label>Kata sandi<input name="password" type="password" autocomplete="current-password" required></label><button type="submit" class="btn btn-primary">Login dan Buka Pesan</button></form>`:esc(data.error||'Backend belum aktif. Konfigurasi server diperlukan untuk menerima pesan otomatis.')};return}
 inboxItems=Array.isArray(data.items)?data.items:[];inboxUnread=Number(data.unread)||0;
 const arriving=inboxKnownIds?inboxItems.filter(m=>!m.read&&!inboxKnownIds.has(m.id)):[];inboxKnownIds=new Set(inboxItems.map(m=>m.id));updateInboxBadge();
 if(arriving.length)toast(`${arriving.length} konsultasi baru masuk. Klik ikon lonceng untuk membuka Pesan Masuk.`);
 if(route==='inbox'){const status=$('#inboxStatus'),list=$('#inboxList');if(!status||!list)return;status.textContent=`${data.simulation?'SIMULASI LOKAL — tidak ada pengiriman eksternal. ':''}${inboxItems.length} pesan tercatat · ${inboxUnread} belum dibaca`;list.innerHTML=inboxItems.length?`<div class="kd-inbox-grid">${inboxItems.map(m=>`<article class="kd-inbox-card ${m.read?'is-read':'is-unread'}"><div class="kd-inbox-card-head"><div><span class="kd-inbox-label">${m.simulation?'SIMULASI | ':''}${m.read?'Sudah dibaca':'Baru'}</span><h3>${esc(m.nama)}</h3><small>${esc(m.namaBisnis)} · ${esc(fmtTime(m.date))}</small></div>${m.read?'':`<button type="button" class="btn btn-light btn-xs" data-message-id="${attr(m.id)}">Tandai dibaca</button>`}</div><p>${esc(m.pesan)}</p><div class="kd-inbox-meta"><span><b>Layanan:</b> ${esc(m.jenisWebsite)}</span><span><b>Anggaran:</b> ${esc(m.anggaran)}</span><span><b>Target:</b> ${esc(m.targetSelesai)}</span><span><b>Email:</b> ${esc(m.email||'-')}</span><span><b>Kanal:</b> ${m.kirimVia==='email'?'Email':'WhatsApp'}</span><span class="kd-inbox-delivery ${attr(m.delivery?.[m.kirimVia]||'pending')}">${esc(({simulated:'SIMULASI — pengiriman tidak dilakukan',sent:'Diterima layanan pengiriman',failed:'Pengiriman gagal',not_configured:'Pengiriman belum aktif',pending:'Menunggu pengiriman'})[m.delivery?.[m.kirimVia]]||'Status pengiriman belum tersedia')}</span></div><a href="https://wa.me/${attr(String(m.wa||'').replace(/\D/g,''))}" target="_blank" rel="noopener noreferrer" class="btn btn-light btn-xs"><i class="fa-brands fa-whatsapp" aria-hidden="true"></i> Balas via WhatsApp</a></article>`).join('')}</div>`:'<p class="kd-inbox-empty">Belum ada konsultasi yang masuk.</p>';}
 }catch{if(route==='inbox'&&!silent){const el=$('#inboxStatus');if(el)el.textContent='Tidak dapat menghubungkan ke server. Periksa koneksi.'}}finally{inboxLoading=false}}
async function serverInboxLogin(ev){ev.preventDefault();if(inboxAuthenticating)return;inboxAuthenticating=true;const data=Object.fromEntries(new FormData(ev.target));const btn=ev.target.querySelector('button');btn.disabled=true;try{const res=await fetch('/api/admin-session',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!res.ok)throw Error((await res.json().catch(()=>({}))).error||'Login server ditolak');toast('Login server berhasil');inboxAuthenticating=false;await loadInbox()}catch(e){toast(e.message,'error')}finally{inboxAuthenticating=false;btn.disabled=false}}
async function markInboxRead(id){if(!id)return;try{const res=await (window.KotekaConsultation?.request || fetch)('/api/inbox',{method:'PATCH',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});if(!res.ok)throw Error('Pesan belum berhasil ditandai');await loadInbox()}catch(e){toast(e.message,'error')}}
