 $('#loginForm').addEventListener('submit',async ev=>{
  ev.preventDefault();const email=$('#loginEmail').value.trim().toLowerCase(),password=$('#loginPassword').value,button=ev.target.querySelector('button[type="submit"]');if(button.disabled)return;
  button.disabled=true;const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);
  try{
   let res,body={};try{res=await fetch('/api/admin-session',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password}),signal:controller.signal});body=await res.json().catch(()=>({}));}catch{}
   const serverLogin=res?.ok&&body.authenticated===true;
   const localOnly=(!res||[404,405,501,503].includes(res.status)||res.ok&&!('authenticated' in body))&&email===DEMO_USER&&password===DEMO_PASS;
   if(serverLogin||localOnly){sessionStorage.setItem(AUTH,'ok');$('#loginError').hidden=true;inboxKnownIds=null;writeLog('system','Autentikasi',serverLogin?'Login administrator server berhasil':'Login ruang kerja lokal berhasil');authView();if(localOnly)toast(window.KotekaConsultation?.localPreview?'Mode simulasi lokal aktif. Pesan dummy masuk ke dashboard pada browser ini.':'Mode lokal aktif. Pesan dan notifikasi otomatis memerlukan konfigurasi server.');}
   else{$('#loginError').textContent=body.error||'Email atau kata sandi tidak sesuai, atau server tidak dapat dihubungi.';$('#loginError').hidden=false;}
  }finally{clearTimeout(timer);button.disabled=false;}
 });
