 global.addEventListener('keydown',ev=>{if(ev.key==='ArrowDown'||ev.key==='ArrowUp'){let opts=$$('[data-search-hit]');if(!opts.length)return;ev.preventDefault();let index=opts.findIndex(x=>x===document.activeElement);(opts[(index+(ev.key==='ArrowDown'?1:opts.length-1))%opts.length]||opts[0]).focus()}if(ev.key==='Escape')closeSearch();if(ev.key==='Enter'){let first=$('[data-search-hit]');if(first){ev.preventDefault();first.click()}}});
